package com.android.tools.lint.checks;

public class StateListDetector extends Detector implements Detector.XmlScanner {

    public static final Issue ISSUE = Issue.create(
        "StateListReachable",
        "Unreachable state in a `<selector>`",
        "In a selector, only the last child in the state list should omit a state qualifier. "
            + "If not, all subsequent items in the list will be ignored since the given item will match all states.",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(StateListDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    @Override
    public List<String> getApplicableElements() {
        return Arrays.asList("selector");
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        NodeList children = element.getChildNodes();
        int count = children.getLength();
        // Collect item elements
        // find last item index
        int lastItemIndex = -1;
        for (int i=0; i<count; i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && "item".equals(child.getLocalName())) {
                lastItemIndex = i;
            }
        }
        if (lastItemIndex < 0) return;
        for (int i=0; i<lastItemIndex; i++) {
            Node child = children.item(i);
            if (child.getNodeType() != Node.ELEMENT_NODE || !"item".equals(child.getLocalName())) {
                continue;
            }
            Element item = (Element) child;
            if (!hasStateQualifier(item)) {
                context.report(ISSUE, item, context.getLocation(item),
                    "Only the last `<item>` in a `<selector>` should omit a state qualifier; this item matches all states and causes subsequent items to be ignored.");
            }
        }
    }

    private static boolean hasStateQualifier(Element item) {
        NamedNodeMap attrs = item.getAttributes();
        for (int i=0, n=attrs.getLength(); i<n; i++) {
            Node attr = attrs.item(i);
            String name = attr.getLocalName();
            if (name != null && name.startsWith("state_")) {
                return true;
            }
        }
        return false;
    }
}

