import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class StateListDetector extends ResourceXmlDetector {
    public static final Issue ISSUE = Issue.create(
            "StateListReachable",
            "Unreachable state in a `<selector>`",
            "In a selector, only the last child in the state list should omit a state qualifier. "
                    + "If not, all subsequent items in the list will be ignored since the given "
                    + "item will match all.",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(StateListDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_SELECTOR);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        // Iterate through child items
        Node child = element.getFirstChild();
        int index = 0;
        int itemCount = 0;
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getNodeName())) {
                itemCount++;
            }
            child = child.getNextSibling();
        }

        child = element.getFirstChild();
        int currentItemIndex = 0;
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getNodeName())) {
                Element item = (Element) child;
                currentItemIndex++;
                if (currentItemIndex < itemCount && hasNoStateAttributes(item)) {
                    context.report(ISSUE, item, context.getLocation(item),
                            "Unreachable state: this item is not the last state and has no "
                                    + "state qualifiers, so all subsequent items will be ignored");
                }
            }
            child = child.getNextSibling();
        }
    }

    private static boolean hasNoStateAttributes(@NonNull Element item) {
        // Check if the item has any state_* attributes
        // The namespace should be android
        // We can iterate attributes
        org.w3c.dom.NamedNodeMap attributes = item.getAttributes();
